<script>
(()=>{
 const form=document.getElementById('wf-egress-form'),host=document.getElementById('wf-egress-lines'),tpl=document.getElementById('wf-egress-line-template'),income=document.getElementById('wf-egress-income'),center=document.getElementById('wf-egress-center'),area=document.getElementById('wf-egress-area'),receiver=document.getElementById('wf-egress-receiver'),productResults=document.getElementById('wf-egress-product-results');let activeProductInput=null,productTimer=null,productController=null;
 const money=value=>window.InvMoney.formatAmount(value),priceMoney=value=>window.InvMoney.formatPrice(value);
 function headerReady(){if(!form)return false;const required=[document.getElementById('wf-egress-date'),center,document.getElementById('wf-egress-detail')],missing=required.find(field=>!String(field?.value||'').trim());if(missing){missing.focus();missing.reportValidity();return false}receiver.value=center.value;area.value=center.selectedOptions[0]?.dataset.area||'';return true}
 function selectRow(row){row.querySelector('.wf-row-select').checked=true;const item=row.querySelector('.wf-item');document.getElementById('wf-selected-group').textContent=item.dataset.group||'—';document.getElementById('wf-selected-stock').textContent=item.value?(item.dataset.stock||'0'):'—';document.getElementById('wf-selected-price').textContent=item.value?priceMoney(item.dataset.price):'—'}
 function refresh(){if(!host)return;let total=0;[...host.children].forEach((row,index)=>{const item=row.querySelector('.wf-item'),stock=Number(item.dataset.stock||0),price=Number(item.dataset.price||0),qty=Math.max(0,Number(row.querySelector('.wf-quantity').value||0));row.querySelector('.wf-line-income').textContent=income?.value||'0';row.querySelector('.wf-line-group').textContent=item.dataset.group||'—';row.querySelector('.wf-line-stock').textContent=stock;row.querySelector('.wf-line-price').textContent=priceMoney(price);row.querySelector('.wf-line-subtotal').textContent=money(price*qty);const balance=row.querySelector('.wf-line-balance');balance.textContent=stock-qty;balance.classList.toggle('negative',stock-qty<0);item.name=`items[${index}][item_id]`;row.querySelector('.wf-quantity').name=`items[${index}][cantidad]`;total+=price*qty;if(row.querySelector('.wf-row-select').checked)selectRow(row)});document.getElementById('wf-egress-total').textContent=money(total);document.getElementById('wf-summary-total').textContent=money(total);document.getElementById('wf-egress-count').textContent=host.children.length+' producto'+(host.children.length===1?'':'s')}
 function hideProductResults(){productResults?.classList.remove('active');if(productResults)productResults.innerHTML='';activeProductInput=null}
 function chooseEgressProduct(row,product){const item=row.querySelector('.wf-item'),search=row.querySelector('.wf-product-search'),code=product.codigo||product.codigo_maestro||product.codigo_clasificacion||product.codigo_interno||product.secuencial||'';item.value=product.id;item.dataset.group=product.grupo_nombre||'Sin grupo';item.dataset.stock=Number(product.existencia||0);item.dataset.price=Number(product.precio_promedio||0);search.value=(code?code+' · ':'')+(product.nombre||'');search.setCustomValidity('');hideProductResults();selectRow(row);refresh()}
 function renderProductResults(input,products){activeProductInput=input;if(!productResults)return;productResults.innerHTML='';const rect=input.getBoundingClientRect(),width=Math.min(Math.max(rect.width,470),window.innerWidth-24);productResults.style.width=width+'px';productResults.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-width-12))+'px';productResults.style.top=Math.max(12,Math.min(rect.bottom+5,window.innerHeight-310))+'px';if(products[0]?.loading)productResults.innerHTML='<div class="wf-product-empty"><i class="fa-solid fa-spinner fa-spin"></i> Buscando productos…</div>';else if(!products.length)productResults.innerHTML='<div class="wf-product-empty">No se encontraron productos. Pruebe otro código, marca o palabra.</div>';else products.forEach(product=>{const button=document.createElement('button'),copy=document.createElement('div'),title=document.createElement('strong'),detail=document.createElement('small'),stock=document.createElement('span'),code=product.codigo||product.codigo_maestro||product.codigo_clasificacion||product.codigo_interno||product.secuencial||'';button.type='button';button.className='wf-product-option';title.textContent=(code?code+' · ':'')+(product.nombre||'');detail.textContent=[product.codigo_interno?'Interno '+product.codigo_interno:'',product.codigo_clasificacion?'Clasif. '+product.codigo_clasificacion:'',product.grupo_nombre||'Sin grupo',product.marca||'',product.unidad_abrev||product.unidad_nombre||''].filter(Boolean).join(' · ');stock.textContent='Existencia '+Number(product.existencia||0)+'\n'+priceMoney(product.precio_promedio);copy.append(title,detail);button.append(copy,stock);button.onclick=()=>chooseEgressProduct(input.closest('tr'),product);productResults.appendChild(button)});productResults.classList.add('active')}
 async function searchEgressProducts(input,query){if(productController)productController.abort();productController=new AbortController();renderProductResults(input,[{loading:true}]);try{const response=await fetch('index.php?route=egresos&action=buscarProductosRequisicion&q='+encodeURIComponent(query),{signal:productController.signal}),data=await response.json();if(activeProductInput===input)renderProductResults(input,data.productos||[])}catch(error){if(error.name!=='AbortError')renderProductResults(input,[])}}
 function queueEgressProductSearch(input){activeProductInput=input;const item=input.closest('tr').querySelector('.wf-item');item.value='';input.setCustomValidity('Seleccione un producto de los resultados.');refresh();clearTimeout(productTimer);const query=input.value.trim();if(query.length<2)return hideProductResults();productTimer=setTimeout(()=>searchEgressProducts(input,query),220)}
 function addLine(){if(!host||!tpl)return;const row=tpl.content.firstElementChild.cloneNode(true),search=row.querySelector('.wf-product-search');search.oninput=()=>queueEgressProductSearch(search);search.onkeydown=event=>{if(event.key==='Escape')hideProductResults()};row.querySelector('.wf-quantity').oninput=()=>{selectRow(row);refresh()};row.onclick=event=>{if(!event.target.closest('input[type=search],input[type=number],button'))selectRow(row)};host.appendChild(row);selectRow(row);refresh()}
 document.getElementById('wf-add-egress-line')?.addEventListener('click',addLine);document.getElementById('wf-delete-selected')?.addEventListener('click',()=>{const selected=host.querySelector('.wf-row-select:checked');if(selected)selected.closest('tr').remove();if(!host.children.length)addLine();refresh()});income?.addEventListener('change',refresh);center?.addEventListener('change',()=>{receiver.value=center.value;area.value=center.selectedOptions[0]?.dataset.area||''});document.addEventListener('click',event=>{if(!event.target.closest('.wf-product-results,.wf-product-cell'))hideProductResults()});document.addEventListener('scroll',event=>{if(!(event.target instanceof Element)||!event.target.closest('.wf-product-results'))hideProductResults()},true);window.addEventListener('resize',hideProductResults);
 form?.addEventListener('submit',event=>{if(!headerReady()){event.preventDefault();return}const rows=[...host.children],ids=rows.map(row=>row.querySelector('.wf-item').value).filter(Boolean),empty=ids.length!==rows.length,bad=rows.some(row=>Number(row.querySelector('.wf-quantity').value||0)>Number(row.querySelector('.wf-item').dataset.stock||0));if(!rows.length||empty||new Set(ids).size!==ids.length||bad){event.preventDefault();alert(!rows.length||empty?'Seleccione al menos un producto.':bad?'Una cantidad supera la existencia disponible.':'No repita productos en el mismo egreso.');return}if(!confirm('Se restarán las cantidades indicadas de la existencia y se registrará el movimiento en Kardex. ¿Confirmar egreso?'))event.preventDefault()});
 if(host&&!host.children.length)addLine();
 const historyConfigNode=document.getElementById('wf-egress-list-config');let historyTable=null,historyLoaded=false;if(historyConfigNode&&window.jQuery&&$.fn?.DataTable){const cfg=JSON.parse(historyConfigNode.textContent),iso=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,esc=value=>$('<div>').text(value==null?'':String(value)).html();const setDates=type=>{const today=new Date(`${cfg.hoy}T12:00:00`);let from='',to='';if(type==='hoy')from=to=iso(today);if(type==='mes'){from=iso(new Date(today.getFullYear(),today.getMonth(),1));to=iso(today)}if(type==='anio'){from=iso(new Date(today.getFullYear(),0,1));to=iso(today)}document.getElementById('wf-egress-from').value=from;document.getElementById('wf-egress-to').value=to};setDates('hoy');historyTable=$('#wf-egress-history').DataTable({processing:true,serverSide:true,deferLoading:0,searchDelay:350,pageLength:10,lengthMenu:[[10,25,50,100],[10,25,50,100]],order:[[1,'desc']],responsive:true,ajax:{url:cfg.url,data:d=>{d.fecha_desde=document.getElementById('wf-egress-from').value;d.fecha_hasta=document.getElementById('wf-egress-to').value}},columns:[{data:'secuencial',render:v=>`<strong class="wf-code">${esc(v)}</strong>`},{data:'fecha'},{data:'documento_origen',defaultContent:'Sin referencia',render:v=>esc(v||'Sin referencia')},{data:'area_destino',defaultContent:'—'},{data:'responsable'},{data:'motivo'},{data:'total_items',className:'dt-body-center'}],dom:'<"inv-dt-top"lf>rt<"inv-dt-footer"ip>',language:{search:'Buscar:',searchPlaceholder:'Egreso, destino o responsable…',processing:'Consultando egresos…',lengthMenu:'Mostrar _MENU_',info:'Mostrando _START_ a _END_ de _TOTAL_',infoEmpty:'Sin registros',zeroRecords:'No se encontraron egresos.',paginate:{previous:'Anterior',next:'Siguiente'}}});historyTable.on('draw',()=>{if(historyLoaded)document.getElementById('wf-egress-count-history').innerHTML=`<i class="fa-solid fa-circle-check"></i> ${historyTable.page.info().recordsDisplay} registro(s)`});const load=()=>{historyLoaded=true;document.getElementById('wf-egress-empty').hidden=true;document.getElementById('wf-egress-table-shell').hidden=false;historyTable.columns.adjust();if(historyTable.responsive)historyTable.responsive.recalc();const button=document.getElementById('wf-egress-show');button.disabled=true;button.querySelector('span').textContent='Consultando…';historyTable.ajax.reload(()=>{document.getElementById('wf-egress-count-history').innerHTML=`<i class="fa-solid fa-circle-check"></i> ${historyTable.page.info().recordsDisplay} registro(s)`;button.disabled=false;button.querySelector('span').textContent='Actualizar datos'},true)};document.getElementById('wf-egress-show').onclick=load;document.querySelectorAll('[data-eg-period]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-eg-period]').forEach(x=>x.classList.remove('active'));button.classList.add('active');setDates(button.dataset.egPeriod);if(historyLoaded)load()});['wf-egress-from','wf-egress-to'].forEach(id=>document.getElementById(id).onchange=()=>{if(historyLoaded)load()})}

 let kardexTable=null,kardexLoaded=false;const kardexShell=document.getElementById('wf-kardex-shell'),kardexEmpty=document.getElementById('wf-kardex-empty'),kardexState=document.getElementById('wf-kardex-state');const loadKardex=()=>{if(!window.jQuery||!$.fn?.DataTable)return;kardexShell.hidden=false;kardexEmpty.hidden=true;kardexState.textContent='Consultando…';if(!kardexTable){kardexTable=$('#wf-kardex-table').DataTable({processing:true,serverSide:true,searchDelay:350,pageLength:25,lengthMenu:[[10,25,50,100],[10,25,50,100]],order:[[0,'desc']],responsive:true,ajax:{url:'index.php?route=egresos&action=kardexDataTable',data:d=>{d.tipo=document.getElementById('wf-kardex-type').value;d.fecha_desde=document.getElementById('wf-kardex-from').value;d.fecha_hasta=document.getElementById('wf-kardex-to').value}},columns:[{data:'fecha_movimiento'},{data:'tipo_movimiento',render:v=>`<span class="wf-status ${v==='INGRESO'?'done':'pending'}">${v}</span>`},{data:'item_codigo',render:v=>`<code class="wf-code">${String(v||'—').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}</code>`},{data:'item_nombre'},{data:'documento_secuencial'},{data:'entrada'},{data:'salida'},{data:'saldo_resultante'},{data:'responsable',defaultContent:'—'},{data:'observaciones',defaultContent:''}],dom:'<"rq-dt-tools"Bl>rt<"rq-dt-footer"ip>',buttons:$.fn.dataTable.Buttons?[{extend:'excelHtml5',text:'Excel',title:'Kardex_filtrado'},{extend:'print',text:'Imprimir',title:'Kardex de productos'}]:[],language:{processing:'Consultando Kardex…',emptyTable:'No existen movimientos para los filtros seleccionados.',zeroRecords:'No se encontraron movimientos.',lengthMenu:'Mostrar _MENU_',info:'Mostrando _START_ a _END_ de _TOTAL_',infoEmpty:'Sin registros',paginate:{previous:'Anterior',next:'Siguiente'}}});kardexTable.on('draw',()=>{kardexState.textContent=kardexTable.page.info().recordsDisplay+' movimiento(s)'})}else{kardexTable.ajax.reload()}kardexLoaded=true;const term=document.getElementById('wf-kardex-search').value.trim();kardexTable.search(term).draw()};document.getElementById('wf-kardex-show')?.addEventListener('click',loadKardex);document.getElementById('wf-kardex-search')?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();loadKardex()}});document.getElementById('wf-kardex-clear')?.addEventListener('click',()=>{['wf-kardex-search','wf-kardex-type','wf-kardex-from','wf-kardex-to'].forEach(id=>document.getElementById(id).value='');if(kardexLoaded)loadKardex()});
})();
